-- 15/11/2026 — Cidades e locais de Dantsen, Marana e Luna.
--
-- Usuário: "vamos fazer a extração e preencher as cidades e locais de mais alguns
-- reinos" — continuação de 08/11 (Verrogar, Abadom, Calco, Levânia, Ludgrim,
-- Eredra), seguindo a ordem do livro: 3.5 Dantsen, 3.6 Marana, 3.7 Luna.
-- Só cidades e locais; pessoas e textos dos reinos ficam para outro pedido.
-- Fonte: tagmar/reinos.pdf (págs. 56–84), escritos com a skill cronista-de-tagmar.
-- Os três reinos existem com slug gerado pela tela (novo-reino-h24-…).
-- Idempotente: ON CONFLICT (slug) DO NOTHING; a capital só entra se estiver vazia.

BEGIN;

-- ── dantsen (novo-reino-h24-18b6a932) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$leon$t$, $t$Léon$t$, $t$novo-reino-h24-18b6a932$t$, true, NULL, $t$Rei Azuma Olives I, do Castelo da Bruma; a cidade tem prefeito, Cedril Valtore$t$, $t$Maira e Sevides, com templos grandes e bibliotecas próprias. Ganis é honrada pela gente do mar.$t$, $t$Vive do porto, um dos maiores do Mundo Conhecido, menor só que o de Muli, em Conti. Nos dias de frota grande, o cais se enche de mercadorias de toda Tagmar e de objetos que nenhum dantseniano sabe nomear.$t$, $t$Capital de Dantsen e a única cidade grande do reino. Foi fundada em 405 D.C. por Leônio de Alimarus, na foz do Rio Aura. O centro antigo fica a uns dez quilômetros do porto: casas de carvalho e de outras madeiras de lei, e só as construções novas em pedra. Ali estão o Castelo da Bruma, sede do governo, e as moradas dos nobres e dos grandes mercadores, entre hospedarias, tabernas e estábulos.
Na Praça do Enforcado, onde antigamente se executavam criminosos, hoje param as caravanas e ficam as principais casas de comércio. Pelo porto, na rota para o oceano do sul, Léon se acostumou ao estranho: criaturas raras nas mãos dos mercadores, como mercadoria ou como guarda, línguas desconhecidas em cada esquina, marinheiros com histórias de povos do mar e peixes gigantes. A mistura continua, agora sob a sombra da guerra.
A cidade tem quatro grandes bibliotecas. A do Castelo da Bruma é também museu e galeria, com esculturas, pinturas, armas antigas e documentos de tempos que só os elfos lembram, e quem cuida dela é o Barão Felas Irlim. As dos templos de Maira e de Sevides ficam a cargo dos sacerdotes. A pública ocupa um andar da prefeitura e cobra cinco moedas de cobre de entrada; nas outras três, só se entra com licença dada em pessoa pelo curador.
A milícia do porto, firme em tempos de paz, está hoje reduzida e corrompida. Sobre uma encosta íngreme junto ao cais principal fica o Forte do Recife, a prisão do reino.$t$, $t$Corre em Léon que Eredra vai fechar as fronteiras e cortar o comércio, deixando Dantsen sem o único vizinho que lhe resta.
Dizem também que batedores viram piratas de Porto Livre se preparando para saquear a costa, com um barão chamado Melkair à frente, e que enviados com o selo da casa Maximus lhe teriam prometido perdão em Verrogar.$t$, false),
($t$calinior$t$, $t$Calinior$t$, $t$novo-reino-h24-18b6a932$t$, false, NULL, $t$Perizi Marcas, senhor da cidade e líder da Liga da Concha$t$, NULL, $t$Cidade do porto do norte, de praias limpas e peixe farto. Ao longo das estradas há lavouras e plantações de árvores cujas castanhas e sementes dão tinta para tecidos. O comércio está nas mãos da Liga da Concha.$t$, $t$Calinior é a cidade do porto do norte, conhecida pelas praias de água clara. O cais é novo e vive em reforma. Os mercadores da Liga da Concha pagam do próprio bolso uma milícia para livrar os fregueses dos gatunos e das bestas que rondam Dantsen.
Quando as tropas de Verrogar avançaram para cá, quase sem encontrar resistência, muita gente fugiu. A Liga mantém o comércio como pode: seus chefes já vão morando em Léon e deixam prepostos tocando os negócios na cidade. As montanhas de Solomor, perigosas de atravessar, são uma das razões de Verrogar ainda não ter entrado em Calinior.$t$, $t$Dizem que Perizi Marcas vende a Verrogar o movimento das tropas dantsenianas e abriga espiões verrogaris de passagem. Já teria comprado casa em Verrogar e cobiçaria as terras em volta, e Attos II lhe teria prometido um título menor de nobreza se os seus serviços pesarem no fim da guerra.$t$, false),
($t$novini$t$, $t$Novini$t$, $t$novo-reino-h24-18b6a932$t$, false, NULL, $t$Irgum Foicero, prefeito$t$, NULL, $t$Cidade de lavoura, com técnicas de plantio quase tão apuradas quanto as de Eredra. As plantações são enormes, e as de uva ficam ao norte da cidade.$t$, $t$Fica no sul, perto das serras que fazem fronteira com Eredra. O prefeito, Irgum Foicero, é um agricultor humano de pouca fala e muita liderança.
A guerra ainda não chegou aqui como perigo, mas chegou como imposto: as cargas cobradas para pagar o exército já levantaram revoltas entre os trabalhadores e os comerciantes. Nos bosques de Novini nasce na primavera uma flor azulada e rara, de coroa larga e cheiro de mel.$t$, $t$Dizem que os magos procuram a flor azul de Novini para poções de levitação e de mover coisas sem tocá-las, conforme o que se mistura a ela.$t$, false),
($t$porteval$t$, $t$Porteval$t$, $t$novo-reino-h24-18b6a932$t$, false, NULL, NULL, NULL, $t$Foi entreposto e alfândega na fronteira com Verrogar.$t$, $t$Entreposto antigo no noroeste de Dantsen, muito perto da fronteira com Verrogar e de Treva. Suas construções são fortificadas, feitas tanto para cobrar a passagem quanto para a guerra.
Hoje está tomada por tropas. Os generais verrogaris passaram ao largo dela no primeiro avanço, a caminho de Calinior. Agora, com o exército parado, Attos II vê em Porteval mais um pedaço de Dantsen a anexar e um passo para encostar suas fronteiras nas de Eredra.$t$, NULL, false),
($t$isalibel$t$, $t$Isalibel$t$, $t$novo-reino-h24-18b6a932$t$, false, NULL, NULL, NULL, $t$Cria cavalos e pôneis e tem as forjas mais importantes do reino. Todo o metal que Dantsen junta vem para cá, para virar arma, armadura, escudo e elmo.$t$, $t$A única cidade de destaque no centro de Dantsen. Ali meio-elfos e anões vivem como em suas próprias terras, e os humanos são minoria.
Os anões tocam as forjas e mantêm contato direto com os parentes que trabalham nos Montes Dourados. Os meio-elfos criam e adestram os cavalos e pôneis, antes para o serviço e agora para a guerra.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$montes-dourados$t$, $t$Montes Dourados$t$, $t$novo-reino-h24-18b6a932$t$, NULL, $t$Montes da Península do Mar, a ponta de terra que Dantsen estende sobre o oceano. Mineradores de toda parte tiram dali o cobre que o reino usa em panelas, móveis, ligas de metal, armas e armaduras, e que vende para fora.
Em volta dos montes crescem vilas e algumas cidades, sem traçado nenhum além do rumo dos veios. Os anões que trabalham aqui são parentes dos ferreiros de Isalibel.$t$, NULL, false),
($t$forte-do-recife$t$, $t$Forte do Recife$t$, $t$novo-reino-h24-18b6a932$t$, NULL, $t$Prisão do reino, em Léon, sobre uma encosta íngreme junto ao cais principal, de onde se vê tudo o que acontece no porto. Os presos ficam entregues à própria sorte e ao humor dos carcereiros.
O nome vem de um alçapão nos fundos, atrás das celas, que se abre sobre os recifes trinta metros abaixo. Não é raro que os guardas atirem um preso por ali, e o último que ele vê são as ondas quebrando nas pedras.$t$, NULL, false),
($t$rio-aura$t$, $t$Rio Aura$t$, $t$novo-reino-h24-18b6a932$t$, NULL, $t$Rio de águas claras e cheio de peixe, encontrado pelo povo de Leônio de Alimarus depois de atravessar os Montes de Solomor. Os sacerdotes da tribo juraram sentir nele a aura de Ganis, e daí o nome. Leônio seguiu a correnteza crendo que o rio sagrado o levaria ao lugar certo, e na foz fundou Léon.
Ao longo de suas margens fica a melhor lavoura de Dantsen.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$leon$t$ WHERE slug = $t$novo-reino-h24-18b6a932$t$ AND capital IS NULL;

-- ── marana (novo-reino-h24-315d0308) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$sensera$t$, $t$Sensera$t$, $t$novo-reino-h24-315d0308$t$, true, NULL, $t$Rei Augustu Zeneri VI, o Tirano$t$, $t$Selimom, acima de todos; Palier vem logo depois, com muitos elfos dourados no clero.$t$, $t$Tem fazendas em volta e um mercado bem servido de peixes e frutos do mar, trazidos pelas vilas da costa. Hoje está cheia de carpinteiros, pedreiros e artesãos atrás das moedas das obras militares.$t$, $t$Capital de Marana, no sudeste do reino, numa planície fértil de clima ameno, diferente do resto do país. Três portões dão entrada à cidade, ao norte, a oeste e a leste, cada um com sua torre de vigia; por ordem do rei atual, o Portão Norte está ganhando a segunda.
Ao sul, a cidade é guardada pela Colina dos Grifos. Por toda parte há obras, e todas com fins de guerra: o plano é reforçar as defesas antigas e erguer muitas outras, o que desagrada boa parte do povo.
A antiga praça do comércio hoje se chama Praça dos Abutres. Ali há execuções públicas quase todo dia, desde que Augustu subiu ao trono e passou a prender "conspiradores". A pequena masmorra da cidade já não comporta tanta gente, e o ofício de carrasco virou bom negócio. Sensera, uma das cidades mais adiantadas de Tagmar, atravessa um tempo negro.$t$, $t$Há quem diga que a influência de Filanti já chegou à capital, e o povo reza para que não seja verdade.$t$, false),
($t$litoria$t$, $t$Litória$t$, $t$novo-reino-h24-315d0308$t$, false, 4000, $t$Visconde Tolomei Litori XII$t$, NULL, $t$Talvez o maior mercado de Marana, graças ao embarque pelo Rio Lara. Negocia madeira com as vilas de lenhadores em volta de Gironde e leva o trabalho dos seus artesãos até Pontalina, pelo Lago Denégrio. Os pequeninos Cova-Rasa plantam ali legumes que crescem três vezes mais que os comuns e têm gosto de mel.$t$, $t$Cidade do extremo norte de Marana, na divisa com Filanti. São uns quatro mil moradores: três mil humanos, e o resto pequeninos, meio-elfos e alguns elfos florestais vindos da vizinha Gironde. As fazendinhas dos pequeninos se espalham por toda a paisagem em volta.
Litória cresceu para a outra margem do Lara e ali nasceu Litória Nova. Como o rio é a fronteira, aquela margem já é terra de Filanti, embora haja quem jure que o limite é a floresta de Gironde. A briga só não virou guerra pela astúcia do Visconde Tolomei Litori XII, nobre velhaco e bonachão de quase sessenta anos, que conhece bem o ânimo dos homens. Ainda assim, a tensão com os filantianos do norte é grande.
A cidade tem mais de cinquenta casas de negócio entre tabernas, hospedarias, estrebarias e ferrarias, para todo gosto e bolso; as tabernas O Caneco e Coice de Mula são as mais conhecidas. Ultimamente os lobos cinzentos de Filanti atravessam Gironde e atacam a região, e já há quem viva de caçá-los e vender a pele.$t$, $t$O visconde procura uma trilha segura por dentro de Gironde, porque as estradas que contornam a floresta pelo leste podem ser fechadas por causa da peste de Luna.$t$, false),
($t$magiara$t$, $t$Magiara$t$, $t$novo-reino-h24-315d0308$t$, false, NULL, $t$Barão Arturi d'Magiar$t$, $t$Palier e Selimom, cujos sacerdotes tocam as Casas de Cura$t$, $t$Vive das Casas de Cura, que atendem gente de toda a região, e do trabalho dos pequeninos Broca-Terra, mineradores e artífices que tiram metal dos últimos picos dos Palomares.$t$, $t$Cidade do norte, perto dos Montes Palomares, que os bardos chamam de Cidade-hospital. O nome exagera, mas não muito: Magiara tem um grande conjunto de Casas de Cura, e quem tem posses nas cidades vizinhas viaja até aqui para se tratar. Os curandeiros são, na maioria, sacerdotes de Palier e de Selimom, que curam mais com saber de ervas e de mãos do que com milagres, porque os milagres são bênçãos e não se gastam à toa.
A pedido do Rei Elberto, ainda vivo, o Barão Arturi d'Magiar mandou os dois cleros aumentarem a produção de unguentos, emplastros e ervas, para encher os depósitos antes de uma guerra com Verrogar.
Aqui vivem os Broca-Terra, um dos poucos clãs do Mundo Conhecido onde se acha pequenino ferreiro. Guardam a sete chaves o segredo de suas joias e peças, e se dão bem, cada um a seu modo, com os anões da cidade e dos Palomares.$t$, NULL, false),
($t$caliana$t$, $t$Caliana$t$, $t$novo-reino-h24-315d0308$t$, false, 3000, NULL, NULL, $t$Cidade de colégios, ordens e guildas, entre elas a Guilda de Artífices Pedreiros, famosa em toda Tagmar, que formou muitos Mestres de Obras de fora. Os pequeninos Toca-Funda começaram aqui como vendedores de víveres e hoje emprestam dinheiro em todas as cidades do reino.$t$, $t$Cidade-escola de Marana e o maior centro de cultura do reino depois da capital, com uns três mil moradores entre humanos, elfos, meio-elfos e pequeninos. Antes da política de guerra de Augustu, estrangeiros vinham de longe aprender ofício com seus mestres.
Fica perto da Floresta de Fiorna, e elfos florestais são vistos aqui com frequência, de passagem ou de casa feita. Os guardiões da floresta patrulham as cercanias, cada vez mais numerosos à medida que se chega à mata. Por isso os anões passam longe, e quando passam, passam depressa.
É também o maior campo de formação de cadetes e oficiais do reino: a infantaria real e quase todas as milícias fazem aqui pelo menos a base do treino. Karr já percebe que a cidade precisará crescer para dar conta das convocações. Só que a gente de sangue élfico se opõe com força ao rei e ao novo general, e Caliana ameaça ser o lugar onde a guerra civil começa.
Rofir, representante de Caliana no Conselho dos Sábios, desapareceu. Desde então três homens da cidade lideram um levante que cresce do lado de Fiorna.$t$, NULL, false),
($t$chipara$t$, $t$Chipara$t$, $t$novo-reino-h24-315d0308$t$, false, NULL, NULL, NULL, $t$Cria cavalos em planícies verdes de bom pasto. A maior parte dos cavalos de guerra da milícia sai do haras Ferradura de Ouro, do velho Oleg Asrarov, que pelo acordo com o Rei Elberto guardava metade dos animais para a coroa em troca de isenção de impostos. Helena Alinde, meia-elfa, adestra os cavalos dos serviços de correio; Cícero Urunar vende de tudo um pouco.$t$, $t$Cidade em reconstrução. Há cinco anos, dois dragões vindos não se sabe de onde derrubaram mais da metade dos prédios e mataram boa parte do povo. O Rei Elberto, ainda vivo, deu isenções de impostos a quem viesse morar aqui, e Chipara se refaz depressa.
Do desastre nasceu a Escola de Combate Draconiana, que forma guerreiros cuja prova final é enfrentar um dragão e vencê-lo. Até hoje nenhum aluno se formou.
A cavalaria real está voltando para os campos de treino de Chipara. As corridas de cavalos são costume da terra e atraem viajantes que querem ganhar dinheiro; a grande corrida anual, paga pelos três maiores criadores, não acontece desde o ataque, mas eles já anunciam a volta. Com a guerra à vista e o roubo de cavalos crescendo, negociar um bom animal abaixo do preço já não é tão fácil quanto antes.$t$, $t$Dizem que Cícero Urunar quer trazer os grandes cavalos de guerra de Filanti e os corcéis da Levânia, talvez para criá-los à maneira maranense, talvez para cruzar as três raças e tirar uma nova.$t$, false),
($t$lubliama$t$, $t$Lubliama$t$, $t$novo-reino-h24-315d0308$t$, false, 6000, $t$Conde Jacus Lubliam Daconi, por apanágio há quase dez anos, com o conselho da Liga de Forjadores$t$, $t$Blator e, sobretudo, Parom, nos altares dos anões$t$, $t$Faz utensílios de todo tipo, e principalmente armas, com o minério dos Palomares. Vende para o resto do reino e vendia para Verrogar, até as rusgas esfriarem o comércio.$t$, $t$Cidade entre Verrogar e os Montes Palomares: o reino mais guerreiro do Mundo Conhecido de um lado e uma jazida sem fim do outro. Antes de ter nome humano e de entrar nas terras da coroa, já existia ali uma comunidade de anões artífices, e a coroa a fez crescer sem desalojá-los. Dos seis mil moradores, mais de dois mil são anões.
Com o perigo de guerra aberta, as famílias humanas e as poucas de pequeninos começam a ir embora para o centro do reino. Os anões não arredam o pé de suas comunidades no sopé das montanhas, e é isso que ainda faz Verrogar pensar duas vezes antes de entrar: são milhares de anões, com séculos de experiência, aborrecidos e lutando em casa.
A Liga de Forjadores, formada pelos mestres artífices da cidade e comandada pelo ferreiro Rarurg, aconselha o conde. Se a guerra vier, os anões sabem que podem se recolher para dentro da montanha, por corredores que só eles conhecem.$t$, $t$O conde avisou a Liga de que uma caravana de Filanti, mandada pelo próprio rei, viria a Lubliama. Ninguém sabe para quê, Augustu não responde, e os mestres anões temem que por esses nortistas a Seita se aproxime.$t$, false),
($t$rarurg$t$, $t$Rarurg$t$, $t$novo-reino-h24-315d0308$t$, false, NULL, $t$Rarurg, mestre ferreiro anão$t$, $t$Parom, com um templo rústico que é joia da arte anã$t$, NULL, $t$Vila anã incrustada na rocha, a nordeste de Lubliama. Tem o nome do seu morador mais antigo, Rarurg, mestre ferreiro de mais de trezentos anos que na juventude foi aventureiro devoto de Crezir e hoje serve a Parom com fervor. Os séculos só azedaram o seu humor; a sua arte é admirável.
A Parom os anões ergueram aqui um templo rústico, que é uma pérola do seu ofício.$t$, NULL, false),
($t$portiara$t$, $t$Portiara$t$, $t$novo-reino-h24-315d0308$t$, false, 6000, $t$Grão-Duque Altrivius d'Portiara$t$, $t$Ganis, com a grande catedral no centro da cidade; Palier e Selimom também têm templos.$t$, $t$Potência de porto e de comércio. Há sempre umas vinte embarcações no cais, da coroa e de outros reinos, e as caravanas chegam todo dia e partem mais carregadas do que vieram.$t$, $t$A maior cidade de Marana, no extremo sul do reino, rival dos grandes portos de outras terras. Tem uns seis mil moradores, mas não há dia em que menos de sete ou oito mil pessoas andem pelas ruas, comprando, vendendo e tramando. Só a distância do resto do reino a impede de ser a cidade mais importante depois da capital.
Foi a menina dos olhos do Rei Elberto. Com a paz e algumas taxas especiais, prosperou como nunca, e o rei mandou erguer no alto de um platô, de onde se vê todo o porto e o mar, um castelo de verão onde cabia a corte inteira de Sensera. No platô ao lado fica o forte do Grão-Duque Altrivius, nobre de cinquenta anos e cabelos grisalhos, de onde se domina a cidade.
A guerra entre Verrogar e Dantsen bate à porta. Pequenos destacamentos verrogaris já tentaram pilhar Portiara atrás de víveres e dinheiro, e o comércio com esse vizinho quase parou. Altrivius triplicou a milícia e paga quase duzentos mercenários bem treinados que patrulham a fronteira e entram às escondidas em terra inimiga para saber como anda a guerra.$t$, $t$Dizem que Altrivius gasta quase toda a fortuna da família num exército particular, porque teme que Verrogar tente anexar a cidade.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-de-fiorna$t$, $t$Floresta de Fiorna$t$, $t$novo-reino-h24-315d0308$t$, NULL, $t$Grande floresta no leste de Marana e um dos poucos redutos élficos que nunca foram invadidos nem saqueados. Seus elfos florestais e rastreadores a defendem com ardor da mácula das outras raças, sobretudo da humana, e quem não é elfo não é bem-vindo. Os guardiões que vigiam as bordas são conhecidos pela intolerância.
A exceção são os lenhadores das vilas vizinhas, devotos de Maira, que fazem festivais a Vet e a Nil e têm um acordo de corte com os guardiões. Fiorna dá quase toda a madeira do reino, deixa úmido o ar das cidades próximas e fértil o chão.
Como Gironde, Finlaril e a própria Âmiem, é um mundo à parte, que guarda a memória do Segundo Ciclo, talvez do Primeiro. Para quem não é elfo, criatura de Maira ou rastreador, entrar ali e voltar com vida é motivo de grande honra.$t$, $t$Dizem que do lado de Fiorna se forma um levante contra Augustu, puxado por três homens de Caliana, e que ele cresce depressa demais para ser contido.$t$, false),
($t$colina-dos-grifos$t$, $t$Colina dos Grifos$t$, $t$novo-reino-h24-315d0308$t$, NULL, $t$Colina que guarda Sensera pelo sul. Ninguém sabe mais de onde vem o nome.
Pouco antes da morte do Rei Elberto, um grupo de estudiosos achou uma grande caverna na face escarpada da colina. As pesquisas pararam com a morte do rei, e o atual diz não ter dinheiro para essas coisas.$t$, NULL, false)
ON CONFLICT (slug) DO NOTHING;
UPDATE public.reinos SET capital = $t$sensera$t$ WHERE slug = $t$novo-reino-h24-315d0308$t$ AND capital IS NULL;

-- ── luna (novo-reino-h24-5a7b6194) ──
INSERT INTO public.cidades (slug, nome, reino, capital, populacao, governante, religiao, economia, descricao, rumores, compartilhado) VALUES
($t$franges$t$, $t$Franges$t$, $t$novo-reino-h24-5a7b6194$t$, true, NULL, NULL, NULL, $t$Já foi das maiores exportadoras da arte de Luna. Hoje só restam umas poucas mercearias e lojas abertas.$t$, $t$Capital de Luna, ao menos no nome. Foi uma grande cidade, sempre em festa, morada da nobreza e palco de muitas celebrações, sede da monarquia e do Colégio de Magos.
A peste a esvaziou. Resta cerca de um décimo do povo, encolhido nos bairros nobres em volta da praça central e do castelo da antiga dinastia. A maioria dos magos ainda está na cidade, graças a Asvante Nordolerim, mas vive reclusa e só sai para comprar mantimentos e componentes. Se a cura não vier logo, Franges vira cidade fantasma.$t$, $t$Há quem diga que a peste começou em Franges, por culpa dos magos do colégio ou do próprio Rei Navarro III.
Os magos pedem há muito que a sede da escola saia de Franges; Navarro sempre negou, e eles falam entre si e com os de fora por magia.$t$, false),
($t$lagia$t$, $t$Lagia$t$, $t$novo-reino-h24-5a7b6194$t$, false, NULL, NULL, NULL, $t$Vivia dos visitantes dos seus festivais, fonte de renda certa para nobres e grandes mercadores.$t$, $t$Cidade do interior, mais para dentro do que Obrem. Antes da peste era alegre e bonita, com festivais de música e dança que atraíam gente de todo o reino e de terras distantes.
A peste chegou como uma onda do mar e levou quase todos. Dos cinco ou seis mil moradores restam umas dezenas de miseráveis que vagam pelas ruas sem força, ou sem juízo, para ir embora. Hoje é a cidade da fronteira com as terras da peste, que daqui para o oeste aparece só em focos isolados. Por não ser pequena, atrai aventureiros que arriscam a vida atrás do que os mortos e os fugitivos deixaram.$t$, NULL, false),
($t$obrem$t$, $t$Obrem$t$, $t$novo-reino-h24-5a7b6194$t$, false, NULL, $t$Um prefeito$t$, NULL, $t$Vive do Rio Lara: é entreposto dos grandes centros de comércio, de extração e de manufatura da fronteira.$t$, $t$Cidade à margem do Rio Lara, pouco tocada pela peste se comparada às do interior. Foi em Obrem que o Rei Navarro tomou o poder, ao fim da marcha que começou nas cidades do norte.
O prefeito anda inquieto com mensagens sem assinatura que ameaçam destruir a cidade se o povo continuar embarcando para outros reinos. É aqui que mora Stefam Maliarco, um dos guerreiros humanos mais temidos do Mundo Conhecido, que já foi às ilhas independentes. Ele está fora, ninguém sabe onde, e isso aflige ainda mais o prefeito.$t$, NULL, false),
($t$calisto$t$, $t$Calisto$t$, $t$novo-reino-h24-5a7b6194$t$, false, NULL, NULL, NULL, $t$O dinheiro novo dos nobres aquece o comércio e transforma casas em mansões.$t$, $t$Uma das poucas cidades que escaparam do pior da peste, embora o povo fuja às dezenas todo dia. Boa parte dos nobres e ricos do interior se mudou para cá nos últimos meses, e hoje Calisto é a morada da maioria da nobreza de Luna.
Com a tragédia em volta, a cidade vive de bailes e de pompa. Foi também em Calisto que Navarro expulsou as tropas de Filanti, num dos feitos que o levaram ao trono.$t$, NULL, false),
($t$dariati$t$, $t$Dariati$t$, $t$novo-reino-h24-5a7b6194$t$, false, NULL, NULL, $t$Parom, Cambu, Maira Vet, Maira Mon e Selimom, um templo para cada na praça central$t$, NULL, $t$Foi o centro religioso de Luna e uma cidade sem igual no mundo, que acolhia todas as fés sem desprezar nenhuma. Na praça central erguem-se cinco templos imponentes: de Parom, de Cambu, de Maira Vet, de Maira Mon e de Selimom. O templo de Parom era a sede da igreja do deus em Luna.
Foi das primeiras atingidas pela peste. Muitos fugiram, mas a maioria ficou, confiando nos sacerdotes e na palavra dos deuses, e morreu do mesmo jeito. Hoje é uma cidade deserta, onde só andam os fantasmas dos que não acharam descanso.$t$, $t$Não se sabe se Marconde Travescar, alto sacerdote de Parom, ainda está em Dariati. Dizem que, se a peste veio dos deuses, ele está no centro dela.$t$, false),
($t$varteli$t$, $t$Varteli$t$, $t$novo-reino-h24-5a7b6194$t$, false, NULL, NULL, NULL, $t$Fazia um dos vinhos mais caros e apreciados de Luna, de qualidade excepcional.$t$, $t$Vila de vinícolas, cujos nobres produtores viviam recolhidos em suas terras. Foi o lugar de Luna mais terrivelmente atingido pela peste: ela chegou durante o festival anual do vinho, quando quase todos os filhos da vila tinham voltado para a festa. Em menos de um mês não havia ninguém vivo. Foi o maior festival de Varteli, e o último.
O mais estranho é que ninguém no reino parece lembrar quem eram os nobres que faziam o vinho de Varteli.$t$, NULL, false),
($t$porto-coral$t$, $t$Porto Coral$t$, $t$novo-reino-h24-5a7b6194$t$, false, NULL, NULL, NULL, $t$Era o porto de pesca e a base da defesa naval de Luna. Hoje restam algumas dezenas de pescadores pobres demais para fugir.$t$, $t$O único porto de Luna, na Baía dos Corais. Leva o nome das barreiras de coral que crescem ao longo de toda a costa e que, no passado, defendiam a cidade dos piratas e corsários de Porto Livre.
A peste quase a apagou, e com ela foi toda a defesa do mar.$t$, $t$Dizem que piratas de Porto Livre já esperam na costa de Luna, prontos para entrar por Porto Coral assim que tiverem certeza de que a peste deixou a cidade.$t$, false)
ON CONFLICT (slug) DO NOTHING;
INSERT INTO public.locais (slug, nome, reino, populacao, descricao, rumores, compartilhado) VALUES
($t$floresta-de-fiona$t$, $t$Floresta de Fiona$t$, $t$novo-reino-h24-5a7b6194$t$, NULL, $t$Grande floresta do sul de Luna, de árvores como as das terras frias. No centro do reino há campos extensos com bosques, e no extremo norte uma mata mais rala.$t$, NULL, false),
($t$cordilheira-da-navalha$t$, $t$Cordilheira da Navalha$t$, $t$novo-reino-h24-5a7b6194$t$, NULL, $t$Cordilheira que separa Portis de Porto Livre e desce até as terras de Luna. É tida como um dos lugares mais perigosos do Mundo Conhecido.
Nos últimos anos, uns poucos anões se estabeleceram em seus sopés. Sua coragem e seu jeito com a pedra os fazem cobrar caro pelo serviço, e ainda são recebidos com sorriso por quem os contrata. Desde a peste, ficaram ainda mais reclusos.$t$, $t$Os anões andam descontentes com Navarro. Portis empresta dinheiro a Luna e pede em troca parte da produção das minas, e eles temem ver o próprio suor ir embora em impostos.$t$, false)
ON CONFLICT (slug) DO NOTHING;
